function createNeuralNetwork() {
  const networkGroup = new THREE.Group();
  const layerConfig = [5, 8, 6, 3];
  const layerSpacing = 3.2;
  const nodeRadius = 0.28;

  const neurons = [];
  const neuronMaterial = new THREE.MeshPhysicalMaterial({
    color: 0x2196f3,
    metalness: 0.1,
    roughness: 0.15,
    transmission: 0.4,
    thickness: 1.2,
    clearcoat: 0.8,
    clearcoatRoughness: 0.1,
    emissive: 0x0066cc,
    emissiveIntensity: 0.2
  });

  const activeMaterial = new THREE.MeshPhysicalMaterial({
    color: 0x00d4ff,
    metalness: 0.2,
    roughness: 0.1,
    transmission: 0.3,
    emissive: 0x00d4ff,
    emissiveIntensity: 0.8,
    clearcoat: 1.0
  });

  for (let l = 0; l < layerConfig.length; l++) {
    const layerSize = layerConfig[l];
    const layerNodes = [];
    const yOffset = (layerSize - 1) * 0.9;
    const zOffset = (l - layerConfig.length / 2) * layerSpacing;

    for (let n = 0; n < layerSize; n++) {
      const geometry = new THREE.SphereGeometry(nodeRadius, 32, 32);
      const mesh = new THREE.Mesh(geometry, neuronMaterial.clone());
      mesh.position.set(
        zOffset,
        yOffset / 2 - n * 0.9,
        (Math.random() - 0.5) * 0.4
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      mesh.userData = {
        layer: l,
        index: n,
        basePos: mesh.position.clone(),
        activationPhase: Math.random() * Math.PI * 2
      };

      layerNodes.push(mesh);
      networkGroup.add(mesh);

      const glow = new THREE.PointLight(0x00d4ff, 0.3, 3);
      glow.position.copy(mesh.position);
      mesh.add(glow);
      mesh.userData.glow = glow;
    }
    neurons.push(layerNodes);
  }

  const connectionGeometry = new THREE.CylinderGeometry(0.015, 0.015, 1, 8);
  const connectionMaterial = new THREE.MeshStandardMaterial({
    color: 0x8899aa,
    emissive: 0x0044aa,
    emissiveIntensity: 0.1,
    roughness: 0.4,
    metalness: 0.6
  });

  const connections = [];
  for (let l = 0; l < neurons.length - 1; l++) {
    for (let n1 = 0; n1 < neurons[l].length; n1++) {
      for (let n2 = 0; n2 < neurons[l + 1].length; n2++) {
        const start = neurons[l][n1].position;
        const end = neurons[l + 1][n2].position;
        const distance = start.distanceTo(end);

        const cylinder = new THREE.Mesh(connectionGeometry.clone(), connectionMaterial.clone());
        cylinder.geometry = new THREE.CylinderGeometry(0.012, 0.012, distance, 6);

        const mid = new THREE.Vector3().addVectors(start, end).multiplyScalar(0.5);
        cylinder.position.copy(mid);
        cylinder.lookAt(end);
        cylinder.rotateX(Math.PI / 2);

        cylinder.userData = {
          fromLayer: l,
          fromIndex: n1,
          toLayer: l + 1,
          toIndex: n2,
          weight: Math.random() * 2 - 1
        };

        connections.push(cylinder);
        networkGroup.add(cylinder);
      }
    }
  }

  networkGroup.userData = { neurons, connections, layerConfig };
  return networkGroup;
}

function createStockChart() {
  const chartGroup = new THREE.Group();
  chartGroup.position.set(5, -1, 2);
  chartGroup.rotation.y = -0.4;

  const points = [];
  const forecastPoints = [];
  let price = 150;
  const days = 40;

  for (let i = 0; i < days; i++) {
    price += (Math.random() - 0.48) * 3;
    points.push(new THREE.Vector3(i * 0.15 - 3, (price - 150) * 0.1, 0));
    if (i >= 30) {
      forecastPoints.push(new THREE.Vector3(i * 0.15 - 3, (price - 150) * 0.1, 0));
    }
  }

  for (let i = days; i < days + 15; i++) {
    const trend = Math.sin(i * 0.3) * 2 + (Math.random() - 0.5);
    price += trend;
    forecastPoints.push(new THREE.Vector3(i * 0.15 - 3, (price - 150) * 0.1, 0));
  }

  const curve = new THREE.SplineCurve(points);
  const tubeGeo = new THREE.TubeGeometry(curve, 64, 0.04, 8, false);
  const tubeMat = new THREE.MeshPhysicalMaterial({
    color: 0x00c853,
    emissive: 0x00c853,
    emissiveIntensity: 0.4,
    metalness: 0.3,
    roughness: 0.2
  });
  const priceLine = new THREE.Mesh(tubeGeo, tubeMat);
  chartGroup.add(priceLine);

  const forecastCurve = new THREE.SplineCurve(forecastPoints);
  const forecastGeo = new THREE.TubeGeometry(forecastCurve, 40, 0.03, 6, false);
  const forecastMat = new THREE.MeshStandardMaterial({
    color: 0xffb300,
    emissive: 0xff6d00,
    emissiveIntensity: 0.5,
    roughness: 0.3
  });
  const forecastLine = new THREE.Mesh(forecastGeo, forecastMat);
  forecastLine.position.z = 0.05;
  chartGroup.add(forecastLine);

  const gridHelper = new THREE.GridHelper(8, 40, 0xccddee, 0xeef2f6);
  gridHelper.rotation.x = Math.PI / 2;
  gridHelper.position.z = -0.5;
  chartGroup.add(gridHelper);

  const axesGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-3, -2, 0),
    new THREE.Vector3(3.5, -2, 0),
    new THREE.Vector3(-3, -2, 0),
    new THREE.Vector3(-3, 2, 0)
  ]);
  const axes = new THREE.Line(axesGeo, new THREE.LineBasicMaterial({ color: 0x556677 }));
  chartGroup.add(axes);

  return chartGroup;
}

function createDataPanel() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  function updateTexture(time) {
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, 512, 256);

    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 2;
    ctx.strokeRect(10, 10, 492, 236);

    ctx.fillStyle = '#1e293b';
    ctx.font = 'bold 24px Arial';
    ctx.fillText('AI Trading Metrics', 30, 45);

    ctx.fillStyle = '#334155';
    ctx.font = '18px monospace';

    const accuracy = (92.4 + Math.sin(time) * 0.3).toFixed(1);
    const sharpe = (1.85 + Math.cos(time * 0.7) * 0.05).toFixed(2);
    const pnl = (124.7 + Math.sin(time * 0.5) * 2.1).toFixed(1);

    ctx.fillText(`Prediction Accuracy: ${accuracy}%`, 30, 90);
    ctx.fillText(`Sharpe Ratio: ${sharpe}`, 30, 125);
    ctx.fillText(`Daily P&L: +$${pnl}K`, 30, 160);
    ctx.fillText(`Active Positions: 12`, 30, 195);
    ctx.fillText(`Latency: 0.8ms`, 30, 230);

    if (texture) texture.needsUpdate = true;
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;

  const material = new THREE.MeshStandardMaterial({
    map: texture,
    roughness: 0.4,
    metalness: 0.1
  });

  const geometry = new THREE.PlaneGeometry(4, 2);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-5, 0.5, 2);
  mesh.rotation.y = 0.3;

  return { mesh, updateTexture };
}

const neuralNetwork = createNeuralNetwork();
heroGroup.add(neuralNetwork);

const stockChart = createStockChart();
heroGroup.add(stockChart);

const dataPanel = createDataPanel();
heroGroup.add(dataPanel.mesh);

const inputLabels = ['Price', 'Volume', 'RSI', 'MACD', 'Sent.'];
const outputLabels = ['Buy', 'Sell', 'Hold'];

camera.position.set(8, 4, 12);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.5;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  const neurons = neuralNetwork.userData.neurons;
  const connections = neuralNetwork.userData.connections;

  for (let l = 0; l < neurons.length; l++) {
    for (let n = 0; n < neurons[l].length; n++) {
      const neuron = neurons[l][n];
      const phase = neuron.userData.activationPhase;

      const activation = Math.sin(t * 2 + phase + l * 0.8) * 0.5 + 0.5;
      neuron.material.emissiveIntensity = 0.2 + activation * 0.6;
      neuron.userData.glow.intensity = 0.2 + activation * 0.4;

      neuron.position.y = neuron.userData.basePos.y + Math.sin(t * 1.5 + phase) * 0.05;
    }
  }

  for (let c = 0; c < connections.length; c++) {
    const conn = connections[c];
    const dataPulse = (t * 3 + conn.userData.fromLayer * 2) % 4;
    const intensity = Math.max(0, 1 - Math.abs(dataPulse - 2)) * 0.4;
    conn.material.emissiveIntensity = 0.1 + intensity;
  }

  rimLight.intensity = 0.6 + Math.sin(t * 0.8) * 0.15;

  dataPanel.updateTexture(t);

  heroGroup.rotation.y = t * 0.08;

  controls.update();
  renderer.render(scene, camera);
}

animate();

