  const forecastMat = new THREE.MeshStandardMaterial({
    color: 0xffb300,
    emissive: 0xff6d00,
    emissiveIntensity: 0.5,
    roughness: 0.3
  });
  const forecastLine = new THREE.Mesh(forecastGeo, forecastMat);
  forecastLine.position.z = 0.05;
  chartGroup.add(forecastLine);

  const gridHelper = new THREE.GridHelper(8, 40, 0xccddee, 0xeef2f6);
  gridHelper.rotation.x = Math.PI / 2;
  gridHelper.position.z = -0.5;
  chartGroup.add(gridHelper);

  const axesGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-3, -2, 0),
    new THREE.Vector3(3.5, -2, 0),
    new THREE.Vector3(-3, -2, 0),
    new THREE.Vector3(-3, 2, 0)
  ]);
  const axes = new THREE.Line(axesGeo, new THREE.LineBasicMaterial({ color: 0x556677 }));
  chartGroup.add(axes);

  return chartGroup;
}

function createDataPanel() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  function updateTexture(time) {
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, 512, 256);

    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 2;
    ctx.strokeRect(10, 10, 492, 236);

    ctx.fillStyle = '#1e293b';
    ctx.font = 'bold 24px Arial';
    ctx.fillText('AI Trading Metrics', 30, 45);

    ctx.fillStyle = '#334155';
    ctx.font = '18px monospace';

    const accuracy = (92.4 + Math.sin(time) * 0.3).toFixed(1);
    const sharpe = (1.85 + Math.cos(time * 0.7) * 0.05).toFixed(2);
    const pnl = (124.7 + Math.sin(time * 0.5) * 2.1).toFixed(1);

    ctx.fillText(`Prediction Accuracy: ${accuracy}%`, 30, 90);
    ctx.fillText(`Sharpe Ratio: ${sharpe}`, 30, 125);
    ctx.fillText(`Daily P&L: +$${pnl}K`, 30, 160);
    ctx.fillText(`Active Positions: 12`, 30, 195);
    ctx.fillText(`Latency: 0.8ms`, 30, 230);

    if (texture) texture.needsUpdate = true;
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;

  const material = new THREE.MeshStandardMaterial({
    map: texture,
    roughness: 0.4,
    metalness: 0.1
  });

  const geometry = new THREE.PlaneGeometry(4, 2);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-5, 0.5, 2);
  mesh.rotation.y = 0.3;

  return { mesh, updateTexture };
}

